## The Problem: Units Mismatch

The most common cause is a **units mismatch**. JWT's `exp` field is in **seconds** since Unix epoch, but `Date.now()` returns **milliseconds**.

```javascript
// ❌ WRONG - Date.now() is milliseconds, exp is seconds
// Date.now() might be 1700000000000, exp might be 1700000100
// The token's exp will ALWAYS be less than Date.now(), but the comparison is broken
if (decoded.exp < Date.now()) {
    return res.status(401).json({ error: 'Token expired' });
}
// This never triggers correctly - expired tokens pass through
```

## The Fix

```javascript
// ✅ CORRECT - Convert Date.now() to seconds, or multiply exp by 1000
if (decoded.exp < Date.now() / 1000) {
    return res.status(401).json({ error: 'Token expired' });
}

// OR equivalently
if (decoded.exp * 1000 < Date.now()) {
    return res.status(401).json({ error: 'Token expired' });
}
```

## Complete Robust Middleware Example

```javascript
const jwt = require('jsonwebtoken');

function authenticateToken(req, res, next) {
    const authHeader = req.headers['authorization'];
    const token = authHeader && authHeader.split(' ')[1]; // Bearer <token>

    if (!token) {
        return res.status(401).json({ error: 'No token provided' });
    }

    let decoded;
    try {
        // Option 1: Let jsonwebtoken handle expiry automatically (recommended)
        // It checks exp correctly and throws TokenExpiredError if expired
        decoded = jwt.verify(token, process.env.JWT_SECRET);
    } catch (err) {
        if (err.name === 'TokenExpiredError') {
            return res.status(401).json({ error: 'Token expired', expiredAt: err.expiredAt });
        }
        if (err.name === 'JsonWebTokenError') {
            return res.status(401).json({ error: 'Invalid token' });
        }
        return res.status(500).json({ error: 'Token verification failed' });
    }

    // Option 2: Manual check (if you decode without verifying first)
    // Only do this if you have a specific reason to check manually
    const nowInSeconds = Math.floor(Date.now() / 1000);
    if (!decoded.exp) {
        return res.status(401).json({ error: 'Token has no expiry' });
    }
    if (decoded.exp < nowInSeconds) {
        return res.status(401).json({ error: 'Token expired' });
    }

    req.user = decoded;
    next();
}

module.exports = authenticateToken;
```

## Other Things to Check

| Issue | Problem | Fix |
|---|---|---|
| Using `jwt.decode()` | Skips signature/expiry verification | Use `jwt.verify()` instead |
| Missing `exp` in payload | Token never expires | Always set `expiresIn` when signing |
| Clock skew | Server/client clocks differ | Add a small `clockTolerance` buffer |
| Wrong secret | Verification silently fails | Ensure secret matches signing secret |

```javascript
// Signing - always set expiresIn
const token = jwt.sign(
    { userId: user.id },
    process.env.JWT_SECRET,
    { expiresIn: '1h' } // library handles exp in seconds automatically
);

// Verifying with clock skew tolerance (optional)
decoded = jwt.verify(token, process.env.JWT_SECRET, {
    clockTolerance: 30 // allow 30 seconds of skew
});
```

**The simplest fix overall is to use `jwt.verify()` and let the library handle expiry** — it correctly handles the seconds conversion and throws a clear `TokenExpiredError` you can catch.
